CREATE TABLE "ParkingZone" ("id" TEXT NOT NULL, "mallId" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "location" TEXT, "carCapacity" INTEGER NOT NULL DEFAULT 0, "motorCapacity" INTEGER NOT NULL DEFAULT 0, "bicycleCapacity" INTEGER NOT NULL DEFAULT 0, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ParkingZone_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ParkingShift" ("id" TEXT NOT NULL, "shiftNumber" TEXT NOT NULL, "mallId" TEXT NOT NULL, "zoneId" TEXT NOT NULL, "shiftDate" TIMESTAMP(3) NOT NULL, "shiftName" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN', "openingCars" INTEGER NOT NULL DEFAULT 0, "openingMotors" INTEGER NOT NULL DEFAULT 0, "carIn" INTEGER NOT NULL DEFAULT 0, "carOut" INTEGER NOT NULL DEFAULT 0, "motorIn" INTEGER NOT NULL DEFAULT 0, "motorOut" INTEGER NOT NULL DEFAULT 0, "bicycleIn" INTEGER NOT NULL DEFAULT 0, "bicycleOut" INTEGER NOT NULL DEFAULT 0, "peakCars" INTEGER NOT NULL DEFAULT 0, "peakMotors" INTEGER NOT NULL DEFAULT 0, "cashRevenue" DOUBLE PRECISION NOT NULL DEFAULT 0, "nonCashRevenue" DOUBLE PRECISION NOT NULL DEFAULT 0, "notes" TEXT, "closedAt" TIMESTAMP(3), "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ParkingShift_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ParkingIncident" ("id" TEXT NOT NULL, "incidentNo" TEXT NOT NULL, "mallId" TEXT NOT NULL, "zoneId" TEXT NOT NULL, "shiftId" TEXT, "type" TEXT NOT NULL, "severity" TEXT NOT NULL DEFAULT 'MEDIUM', "title" TEXT NOT NULL, "description" TEXT, "status" TEXT NOT NULL DEFAULT 'OPEN', "occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "resolvedAt" TIMESTAMP(3), "workOrderId" TEXT, "reportedById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ParkingIncident_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ParkingZone_mallId_code_key" ON "ParkingZone"("mallId", "code");
CREATE INDEX "ParkingZone_mallId_isActive_idx" ON "ParkingZone"("mallId", "isActive");
CREATE UNIQUE INDEX "ParkingShift_shiftNumber_key" ON "ParkingShift"("shiftNumber");
CREATE UNIQUE INDEX "ParkingShift_zoneId_shiftDate_shiftName_key" ON "ParkingShift"("zoneId", "shiftDate", "shiftName");
CREATE INDEX "ParkingShift_mallId_shiftDate_status_idx" ON "ParkingShift"("mallId", "shiftDate", "status");
CREATE UNIQUE INDEX "ParkingIncident_incidentNo_key" ON "ParkingIncident"("incidentNo");
CREATE INDEX "ParkingIncident_mallId_status_occurredAt_idx" ON "ParkingIncident"("mallId", "status", "occurredAt");
CREATE INDEX "ParkingIncident_zoneId_occurredAt_idx" ON "ParkingIncident"("zoneId", "occurredAt");
CREATE INDEX "ParkingIncident_workOrderId_idx" ON "ParkingIncident"("workOrderId");
ALTER TABLE "ParkingZone" ADD CONSTRAINT "ParkingZone_mallId_fkey" FOREIGN KEY ("mallId") REFERENCES "Mall"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ParkingShift" ADD CONSTRAINT "ParkingShift_mallId_fkey" FOREIGN KEY ("mallId") REFERENCES "Mall"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ParkingShift" ADD CONSTRAINT "ParkingShift_zoneId_fkey" FOREIGN KEY ("zoneId") REFERENCES "ParkingZone"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ParkingShift" ADD CONSTRAINT "ParkingShift_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ParkingIncident" ADD CONSTRAINT "ParkingIncident_mallId_fkey" FOREIGN KEY ("mallId") REFERENCES "Mall"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ParkingIncident" ADD CONSTRAINT "ParkingIncident_zoneId_fkey" FOREIGN KEY ("zoneId") REFERENCES "ParkingZone"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ParkingIncident" ADD CONSTRAINT "ParkingIncident_shiftId_fkey" FOREIGN KEY ("shiftId") REFERENCES "ParkingShift"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ParkingIncident" ADD CONSTRAINT "ParkingIncident_reportedById_fkey" FOREIGN KEY ("reportedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
